{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "One of the EC2 instances is configured with a public IP address, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The EC2 instance metadata service is not configured to require a token, allowing unrestricted access to instance metadata."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Disabled public IP association for all EC2 instances and enabled IMDSv2 by requiring HTTP tokens for metadata access."
}
